    {
      "name": "HasFiniteFPowerSeriesAt.neg",
      "module_name": "Mathlib.Analysis.Analytic.CPolynomial",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {E : Type u_2} {F : Type u_3} [inst : NontriviallyNormedField 𝕜] [inst_1 : NormedAddCommGroup E]\n  [inst_2 : NormedSpace 𝕜 E] [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F] {f : E → F}\n  {pf : FormalMultilinearSeries 𝕜 E F} {x : E} {n : ℕ},\n  HasFiniteFPowerSeriesAt f pf x n → HasFiniteFPowerSeriesAt (-f) (-pf) x n"
    },
    {
      "name": "Polynomial.ofFinsupp_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {a : AddMonoidAlgebra R ℕ}, { toFinsupp := -a } = -{ toFinsupp := a }"
    },
    {
      "name": "Polynomial.roots_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [inst_1 : IsDomain R] (p : Polynomial R), (-p).roots = p.roots"
    },
    {
      "name": "Polynomial.toFinsupp_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] (a : Polynomial R), (-a).toFinsupp = -a.toFinsupp"
    },
    {
      "name": "Poly.neg_apply",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : Poly α) (x : α → ℕ), (-f) x = -f x"
    },
    {
      "name": "Polynomial.reflect_neg",
      "module_name": "Mathlib.Algebra.Polynomial.Reverse",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Ring R] (f : Polynomial R) (N : ℕ), Polynomial.reflect N (-f) = -Polynomial.reflect N f"
    }
  ]
}
